import * as THREE from 'three';
import { Effect, EffectAttribute } from 'postprocessing';

/**
 * Last stage of the Blender look, in the same order as Blender's compositor and view:
 *   Lens Distortion (with dispersion, "fit") -> vignette (scene-linear) -> exposure -> AgX + look (LUT)
 *
 * The LUT is generated by Blender itself (export_web.py write_view_lut), so the curve is not an
 * approximation of AgX: it is Blender's OCIO output sampled on a 65^3 log2 lattice.
 * It returns display-encoded sRGB; it is linearised here because postprocessing re-encodes
 * the final pass to the canvas' sRGB output.
 */
const fragmentShader = /* glsl */ `
precision highp sampler3D;
uniform sampler3D viewLut;
uniform float lutSize;
uniform vec2 lutRange;
uniform float exposureMul;
uniform vec2 vignetteRadius;   // ellipse half-size in uv
uniform float vignetteSoftness; // blur width in uv (along x)
uniform float vignetteAmount;   // Blender Mix (multiply) factor
uniform vec3 lensK;             // per-channel distortion (r, g, b), already x4 as in Blender
uniform float lensScale;        // 1 / (1 + max distortion) or the "fit" variant

// Blender compositor Lens Distortion: centred uv in [-1, 1] per axis, scaled by
// 1 / (1 + sqrt(1 - k d^2)) and mapped back to [0, 1]
vec2 lensDistort( vec2 uv, float k ) {
  vec2 c = ( uv * 2.0 - 1.0 ) * lensScale;
  float s = 1.0 / ( 1.0 + sqrt( max( 0.0, 1.0 - k * dot( c, c ) ) ) );
  return c * s + 0.5;
}

float srgbToLinear1( float c ) {
  return c <= 0.04045 ? c / 12.92 : pow( ( c + 0.055 ) / 1.055, 2.4 );
}

void mainImage( const in vec4 inputColor, const in vec2 uv, out vec4 outputColor ) {
  vec3 c = vec3(
    texture2D( inputBuffer, lensDistort( uv, lensK.r ) ).r,
    texture2D( inputBuffer, lensDistort( uv, lensK.g ) ).g,
    texture2D( inputBuffer, lensDistort( uv, lensK.b ) ).b
  );

  // Ellipse Mask -> Blur -> Mix(Multiply): 1 inside, 0 outside, soft edge
  vec2 p = ( uv - 0.5 ) / vignetteRadius;
  float d = ( length( p ) - 1.0 ) * vignetteRadius.x;
  float mask = 1.0 - smoothstep( -vignetteSoftness, vignetteSoftness, d );
  c *= mix( 1.0, mask, vignetteAmount );

  c *= exposureMul;
  vec3 s = clamp( ( log2( max( c, vec3( 1e-10 ) ) / 0.18 ) - lutRange.x ) / ( lutRange.y - lutRange.x ), 0.0, 1.0 );
  s = ( s * ( lutSize - 1.0 ) + 0.5 ) / lutSize;
  vec3 display = texture( viewLut, s ).rgb;

  outputColor = vec4( srgbToLinear1( display.r ), srgbToLinear1( display.g ), srgbToLinear1( display.b ), inputColor.a );
}
`;

export interface ViewTransformOptions {
  lut: THREE.Data3DTexture;
  lutSize: number;
  lutRange: [number, number];
  exposure: number; // stops, as in Blender
  vignette?: { radius: [number, number]; softness: number; amount: number };
  lens?: { distortion: number; dispersion: number; fit: boolean };
}

/** Same derivation as Blender's compositor (DISTORTION_SCALE = 4, clamped to [-0.999, 1]). */
function lensUniforms(l?: ViewTransformOptions['lens']) {
  const d = l?.distortion ?? 0;
  const disp = l?.dispersion ?? 0;
  const clamp = (v: number) => Math.min(1, Math.max(-0.999, v));
  const k = [clamp(d + disp), clamp(d), clamp(d - disp)];
  const maxK = Math.max(...k);
  const scale = l?.fit && maxK > 0 ? 1 / (1 + 2 * maxK) : 1 / (1 + maxK);
  return { k: new THREE.Vector3(k[0] * 4, k[1] * 4, k[2] * 4), scale };
}

export class ViewTransformEffect extends Effect {
  constructor(o: ViewTransformOptions) {
    const v = o.vignette ?? { radius: [0.5, 0.5], softness: 0.1, amount: 0 };
    const lens = lensUniforms(o.lens);
    super('ViewTransformEffect', fragmentShader, {
      // samples the input at displaced uvs (lens distortion), so it needs its own pass
      attributes: EffectAttribute.CONVOLUTION,
      uniforms: new Map<string, THREE.Uniform>([
        ['viewLut', new THREE.Uniform(o.lut)],
        ['lutSize', new THREE.Uniform(o.lutSize)],
        ['lutRange', new THREE.Uniform(new THREE.Vector2(...o.lutRange))],
        ['exposureMul', new THREE.Uniform(Math.pow(2, o.exposure))],
        ['vignetteRadius', new THREE.Uniform(new THREE.Vector2(...v.radius))],
        ['vignetteSoftness', new THREE.Uniform(v.softness)],
        ['vignetteAmount', new THREE.Uniform(v.amount)],
        ['lensK', new THREE.Uniform(lens.k)],
        ['lensScale', new THREE.Uniform(lens.scale)],
      ]),
    });
  }

  set exposure(stops: number) {
    this.uniforms.get('exposureMul')!.value = Math.pow(2, stops);
  }
}

/** Builds the 3D texture from Blender's strip PNG (x = r + b*N, y = g, top row g = 0). */
export async function loadViewLut(url: string, size: number) {
  const blob = await (await fetch(url)).blob();
  // no colour management or premultiplication: these are data, not an image
  const bmp = await createImageBitmap(blob, { colorSpaceConversion: 'none', premultiplyAlpha: 'none' });
  const canvas = document.createElement('canvas');
  canvas.width = bmp.width;
  canvas.height = bmp.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
  ctx.drawImage(bmp, 0, 0);
  const src = ctx.getImageData(0, 0, bmp.width, bmp.height).data;
  const n = size;
  const data = new Uint8Array(n * n * n * 4);
  for (let b = 0; b < n; b++)
    for (let g = 0; g < n; g++)
      for (let r = 0; r < n; r++) {
        const s = (g * bmp.width + (r + b * n)) * 4;
        const d = ((b * n + g) * n + r) * 4;
        data[d] = src[s];
        data[d + 1] = src[s + 1];
        data[d + 2] = src[s + 2];
        data[d + 3] = 255;
      }
  const tex = new THREE.Data3DTexture(data, n, n, n);
  tex.format = THREE.RGBAFormat;
  tex.type = THREE.UnsignedByteType;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.wrapS = tex.wrapT = tex.wrapR = THREE.ClampToEdgeWrapping;
  tex.unpackAlignment = 1;
  tex.colorSpace = THREE.NoColorSpace;
  tex.needsUpdate = true;
  return tex;
}
